WITH with_prev AS (SELECT *, LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) AS prev_paid_at FROM payments), gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END) AS success_count, SORT_ARRAY(COLLECT_SET(method)) AS method_list, SORT_ARRAY(COLLECT_SET(method)) AS method_list_2, ROUND(AVG(new_group_flag), 2) AS avg_new_group_flag FROM sessionized GROUP BY year_start;
